def verify(x):
    n = len(x)
    diffs = set()
    for i in range(n):
        for j in range(i+1, n):
            d = (j - i, x[j] - x[i])
            if d in diffs:
                return False
            diffs.add(d)
    return True

x = [0, 2, 11, 6, 3, 8, 9, 7, 10, 1, 5, 4, 12]
print(verify(x))
